def no(chaves, *filhos):
    return {"chaves": chaves, "filhos": list(filhos)}

def busca(atual, chave, nivel=1):
    c, i = atual["chaves"], 0
    while i < len(c) and chave > c[i]:
        i += 1
    if i < len(c) and c[i] == chave:
        return nivel
    return busca(atual["filhos"][i], chave, nivel + 1)

a = no([10, 20], no([2, 5]), no([12, 15]), no([22, 25]))
b = no([40, 50], no([32, 35]), no([42, 45]), no([52, 55]))
raiz = no([30], a, b)
print(busca(raiz, 40), busca(raiz, 45))

