def inserir(raiz, palavra):
    no = raiz
    for letra in palavra:
        if letra not in no:
            no[letra] = {}
        no = no[letra]

def contar(no):
    return 1 + sum(contar(filho) for filho in no.values())

raiz = {}
for palavra in ["casa", "caso", "cama", "cor", "cos"]:
    inserir(raiz, palavra)
print(contar(raiz))

