def inserir(no, palavra):
    for letra in palavra:
        no = no.setdefault(letra, {})
    no["$"] = True

def busca(no, palavra):
    for letra in palavra:
        no = no.get(letra, {})
    return "$" in no

raiz = {}
for p in ["carro", "car"]:
    inserir(raiz, p)
print(busca(raiz, "car"), busca(raiz, "carr"), busca(raiz, "carro"))

