def inserir(no, palavra):
    for letra in palavra:
        no = no.setdefault(letra, {"#": 0})
        no["#"] += 1

def com_prefixo(no, prefixo):
    for letra in prefixo:
        no = no.get(letra, {"#": 0})
    return no["#"]

raiz = {}
for p in ["sol", "sola", "solo", "sal", "sono"]:
    inserir(raiz, p)
print(com_prefixo(raiz, "so"), com_prefixo(raiz, "sol"))

